-- 0001_init.sql
--
-- The whole app state of the study app (docs/SPEC.md §5).
--
-- Ids are TEXT (uuid v4 strings generated by the client/server), timestamps
-- are INTEGER epoch milliseconds and the FSRS card state mirrors the ts-fsrs
-- `Card` interface one-to-one so the client can schedule offline and the
-- server can re-validate the exact same way.

-- ---------------------------------------------------------------------------
-- Users, topics and sets
-- ---------------------------------------------------------------------------

CREATE TABLE users (
  id            TEXT PRIMARY KEY,
  created_at    INTEGER NOT NULL,
  -- retention, daily new cap, quiet hours, ...
  settings_json TEXT
);

CREATE TABLE topics (
  id      TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name    TEXT NOT NULL,
  color   TEXT
);

CREATE INDEX topics_user_id ON topics(user_id);

CREATE TABLE sets (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  topic_id    TEXT REFERENCES topics(id) ON DELETE SET NULL,
  title       TEXT NOT NULL,
  description TEXT,
  -- 'manual' | 'csv' | 'mcp' | 'anki'
  source      TEXT NOT NULL DEFAULT 'manual',
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
);

CREATE INDEX sets_user_id ON sets(user_id);
CREATE INDEX sets_topic_id ON sets(topic_id);

-- ---------------------------------------------------------------------------
-- Cards
-- ---------------------------------------------------------------------------

CREATE TABLE cards (
  id           TEXT PRIMARY KEY,
  set_id       TEXT NOT NULL REFERENCES sets(id) ON DELETE CASCADE,
  -- 'mc' is the only implemented type. The column keeps room for
  -- 'short' | 'math' | 'cloze' (Phase 3) without a schema rewrite.
  type         TEXT NOT NULL DEFAULT 'mc',
  front        TEXT NOT NULL,
  back         TEXT NOT NULL,
  -- The four multiple choice options, JSON encoded.
  choices_json TEXT,
  -- Index of the correct option inside choices_json.
  answer_index INTEGER,
  -- 'text' | 'katex'
  render       TEXT NOT NULL DEFAULT 'text',
  -- Hints, image urls, ...
  extra_json   TEXT,
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL,
  deleted_at   INTEGER
);

CREATE INDEX cards_set_id ON cards(set_id);

-- ---------------------------------------------------------------------------
-- Spaced repetition state and review log
-- ---------------------------------------------------------------------------

-- Mirrors the ts-fsrs `Card` interface.
CREATE TABLE card_state (
  card_id        TEXT PRIMARY KEY REFERENCES cards(id) ON DELETE CASCADE,
  due            INTEGER NOT NULL,
  stability      REAL NOT NULL DEFAULT 0,
  difficulty     REAL NOT NULL DEFAULT 0,
  elapsed_days   INTEGER NOT NULL DEFAULT 0,
  scheduled_days INTEGER NOT NULL DEFAULT 0,
  learning_steps INTEGER NOT NULL DEFAULT 0,
  reps           INTEGER NOT NULL DEFAULT 0,
  lapses         INTEGER NOT NULL DEFAULT 0,
  -- 0 = new, 1 = learning, 2 = review, 3 = relearning
  state          INTEGER NOT NULL DEFAULT 0,
  last_review    INTEGER
);

CREATE INDEX card_state_due ON card_state(due);

-- Append only. `client_id` makes the offline sync idempotent.
CREATE TABLE review_logs (
  id             TEXT PRIMARY KEY,
  card_id        TEXT NOT NULL REFERENCES cards(id) ON DELETE CASCADE,
  session_id     TEXT,
  -- 1 = again, 2 = hard, 3 = good, 4 = easy
  rating         INTEGER NOT NULL,
  state          INTEGER NOT NULL,
  due            INTEGER NOT NULL,
  stability      REAL NOT NULL DEFAULT 0,
  difficulty     REAL NOT NULL DEFAULT 0,
  elapsed_days   INTEGER NOT NULL DEFAULT 0,
  scheduled_days INTEGER NOT NULL DEFAULT 0,
  learning_steps INTEGER NOT NULL DEFAULT 0,
  review         INTEGER NOT NULL,
  duration_ms    INTEGER,
  -- Unique per client generated id, so replaying a batch never double counts.
  client_id      TEXT NOT NULL UNIQUE
);

CREATE INDEX review_logs_card_id_review ON review_logs(card_id, review);
CREATE INDEX review_logs_session_id ON review_logs(session_id);

-- ---------------------------------------------------------------------------
-- Sessions and rewards
-- ---------------------------------------------------------------------------

CREATE TABLE sessions (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- The game mode, e.g. 'cast'. Cosmetic only, the scheduler picks the cards.
  mode          TEXT NOT NULL,
  scope_json    TEXT,
  started_at    INTEGER NOT NULL,
  ended_at      INTEGER,
  score         INTEGER NOT NULL DEFAULT 0,
  stats_json    TEXT,
  -- Filled in when the server pays the session out.
  payout_tokens INTEGER
);

CREATE INDEX sessions_user_id ON sessions(user_id);

CREATE TABLE packs (
  id              TEXT PRIMARY KEY,
  name            TEXT NOT NULL,
  theme           TEXT,
  price_tokens    INTEGER NOT NULL DEFAULT 0,
  -- 'core' | 'seasonal'
  kind            TEXT NOT NULL DEFAULT 'core',
  -- NULL window means the pack is always on sale.
  available_from  INTEGER,
  available_until INTEGER,
  sort            INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX packs_availability ON packs(available_from, available_until);

CREATE TABLE critters (
  id      TEXT PRIMARY KEY,
  pack_id TEXT NOT NULL REFERENCES packs(id) ON DELETE CASCADE,
  name    TEXT NOT NULL,
  -- 'common' | 'uncommon' | 'rare' | 'epic' | 'legendary'
  rarity  TEXT NOT NULL,
  vibe    TEXT,
  art_url TEXT
);

CREATE INDEX critters_pack_id ON critters(pack_id);

CREATE TABLE user_critters (
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  critter_id TEXT NOT NULL REFERENCES critters(id) ON DELETE CASCADE,
  -- Duplicates are converted into bonus tokens, but the count is kept.
  count      INTEGER NOT NULL DEFAULT 1,
  first_at   INTEGER NOT NULL,
  PRIMARY KEY (user_id, critter_id)
);

CREATE TABLE wallet (
  user_id    TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  tokens     INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL
);

-- Audit trail of every token change.
CREATE TABLE ledger (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  delta      INTEGER NOT NULL,
  reason     TEXT NOT NULL,
  ref_id     TEXT,
  created_at INTEGER NOT NULL
);

CREATE INDEX ledger_user_id ON ledger(user_id);

-- ---------------------------------------------------------------------------
-- Push notifications and API tokens
-- ---------------------------------------------------------------------------

-- Expo push tokens (the Expo Push Service endpoint plus its keys).
CREATE TABLE push_tokens (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  endpoint   TEXT NOT NULL,
  keys_json  TEXT,
  created_at INTEGER NOT NULL
);

CREATE UNIQUE INDEX push_tokens_endpoint ON push_tokens(endpoint);

-- Bearer tokens for the app (expo-secure-store) and for MCP.
-- Only the hash of the token is stored.
CREATE TABLE api_tokens (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  hash       TEXT NOT NULL,
  label      TEXT,
  scopes     TEXT,
  created_at INTEGER NOT NULL,
  last_used  INTEGER
);

CREATE UNIQUE INDEX api_tokens_hash ON api_tokens(hash);
